import {hearButton,foodArt} from './play-media.mjs';
import {learningInvitations} from './learning-invitations.mjs';
import {starterIngredients} from './cafe-content.mjs';
import {spiralPage,spiralNotes,spiralAnimalArt,spiralPlaceArt} from './living-spiral-ui.mjs';
import {spiralCase,spiralAnimal,spiralPlaces,spiralTarget} from './living-spiral-content.mjs';
import {spiralState,currentSpiral,spiralClosed} from './living-spiral-core.mjs';
import {strands,depths,tags,scienceQuestion,noteQuestion,mathQuestion,scienceReady,readingReady,freshAdaptive} from './living-adaptive-content.mjs';
import {adaptiveSuggestion,setAdaptiveChoice,startAdaptiveSpiral,inspectAdaptive,chooseAdaptive,revealAdaptiveChange,supportAdaptive,submitAdaptive,findAdaptive,carryAdaptive,leaveAdaptive} from './living-adaptive-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const food=t=>starterIngredients.find(x=>x.id===t.ingredientId);
const total=t=>t.packs*t.bites;
const names={science:'Nature clues',reading:'Delivery notes',math:'Parcel math'};
const button=(attrs,text,selected=false,disabled=false)=>`<button type="button" class="secondary ${selected?'selected':''}" ${attrs} ${disabled?'disabled':''}>${text}</button>`;
const hear=(k,text,label)=>hearButton(text,label).replace('data-speak=',`data-adapt-audio="${k}" data-speak=`);
const help=(k,label)=>button(`data-adapt-help="${k}"`,label);
function settings(state){const p=spiralState(state)?.adaptive||freshAdaptive();return `<details class="panel adapt-settings"><summary>How shall our next search grow?</summary><p>Suggestions follow our recent finished visits. Every trail stays open. These choices affect the next search only.</p><div class="spiral-setting-grid">${strands.map(k=>{const s=adaptiveSuggestion(state,k);return `<label>${names[k]}<select data-adapt-choice="${k}"><option value="auto" ${p.choices[k]==='auto'?'selected':''}>Suggested · ${depths[k][s.level-1]}</option>${depths[k].map((label,i)=>`<option value="${i+1}" ${p.choices[k]===i+1?'selected':''}>Choose · ${label}</option>`).join('')}</select><span class="tiny">${esc(s.reason)}</span></label>`;}).join('')}</div><p class="tiny">This is a small practice history, not a reading level, grade, or mastery assessment. Help and narration stay available.</p></details>`;}
function progress(r){const stage=r.found?2:scienceReady(r)?1:0;return `<ol class="adapt-path" aria-label="Our search"><li ${stage===0?'aria-current="step"':''}>1 · Notice</li><li ${stage===1?'aria-current="step"':''}>2 · Follow a note</li><li ${stage===2?'aria-current="step"':''}>3 · Pack for the café</li></ol>`;}
function science(r){const t=r.task,q=scienceQuestion(t),a=spiralAnimal(spiralCase(t.caseId).animal),ps=spiralPlaces(t),s=r.science,last=s.attempts.at(-1);
 const before={kind:a.reason==='nectar'?'flowers':'leaves',damp:a.reason!=='nectar',cover:a.reason!=='nectar',nectar:a.reason==='nectar',observation:a.reason==='nectar'?'Before: open flowers with nectar.':'Before: damp leaf litter beneath cover on land.'};
 const after={...q.changed,kind:a.reason==='nectar'?'buds':'leaves'};
 return `<section class="spiral-need">${spiralAnimalArt(a.id)}<div><p class="place-name">${names.science} · ${depths.science[q.depth-1]}</p><h2>${a.need}</h2><p>We’re restoring places to rest and feed after the storm. Look at the conditions, then follow the café delivery trail.</p>${hear('science',a.name+'. '+a.need,'Hear the animal’s need')}${button('data-adapt-vocabulary',`What does “${a.word}” mean?`)}${s.vocabulary?`<p class="hint" id="adapt-vocabulary">${a.definition}</p>`:''}</div></section><div class="spiral-place-grid">${ps.map((p,i)=>`<article class="spiral-place"><h3>${p.name}</h3>${spiralPlaceArt(p,r.inspected.includes(i))}${button(`data-adapt-inspect="${i}"`,r.inspected.includes(i)?'Look again':'Look closely')}<div id="adapt-clue-${i}">${r.inspected.includes(i)?`<p>${p.observation}</p>${hear('science',p.observation,'Hear this clue')}`:'<p class="tiny">A close look reveals this visit’s conditions.</p>'}</div></article>`).join('')}</div><section class="living-comparison"><h2>Which place meets this need?</h2><fieldset><legend>Use the original picture clues</legend><div class="living-options">${ps.map((p,i)=>button(`data-adapt-science-place="${i}" aria-pressed="${s.place===i}"`,p.name,s.place===i)).join('')}</div></fieldset>${q.depth===3?`<div class="adapt-change">${button('data-adapt-change','See what changes later')}${s.changedShown?`<div id="adapt-change-picture"><h3>A later close-up: something has changed</h3><p class="tiny">Use the first pictures to choose a place. Then compare these close-ups: what would you check again?</p><div class="adapt-before-after"><figure>${spiralPlaceArt(before,true)}<figcaption>${before.observation}</figcaption></figure><figure>${spiralPlaceArt(after,true)}<figcaption>${after.observation}</figcaption></figure></div></div>`:''}</div>`:''}<fieldset><legend>${q.prompt}</legend><div class="living-options adapt-evidence">${q.options.map(o=>button(`data-adapt-science-detail="${o.id}" aria-pressed="${s.detail===o.id}"`,esc(o.text),s.detail===o.id)).join('')}</div></fieldset>${button('data-adapt-submit="science"','Compare our clues',false,s.matched||s.place===null||s.detail===null||q.depth===3&&!s.changedShown)}<p class="spiral-feedback" id="adapt-science-feedback" role="status">${s.matched?'Those clues fit. Inspect the useful place and a contrasting place to follow the note.':last?'Let’s look again: compare the supplied clues with this animal’s need. Another try or an explanation is welcome.':'Try our ideas, or think it through together.'}</p>${help('science','Think it through together')}${s.help?`<div class="hint" id="adapt-science-help"><p>${a.why} In the original picture: ${ps[q.target].observation}</p>${q.depth===3?`<p>${q.changed.observation} ${q.options[0].text}</p>`:''}</div>`:''}</section>${scienceReady(r)?note(r):'<p class="status-note">Look closely at the useful place and at least one other place. Compare our ideas or think together to open the delivery note.</p>'}`;
}
export function tagArt(tag){const shape=tag==='leaf'?'<path d="M14 39Q8 7 44 8Q49 42 14 39Z" fill="#8aa887"/><path d="M12 44L38 16" stroke="#397958" stroke-width="3"/>':tag==='star'?'<path d="m28 6 7 14 16 2-12 12 3 16-14-8-15 8 3-16L5 22l16-2Z" fill="#e9b84a"/>':'<path d="M8 39Q-1 12 28 9Q56 12 48 39L28 48Z" fill="#d9a998"/><path d="m28 43-13-23m13 23V16m0 27 14-23" stroke="#966d50" stroke-width="2"/>';return `<svg class="adapt-tag" viewBox="0 0 56 56" aria-hidden="true">${shape}</svg>`;}
function note(r){const q=noteQuestion(r.task),s=r.reading;return `<section class="living-search adapt-note"><p class="place-name">${names.reading} · ${depths.reading[q.depth-1]}</p><h2 id="adapt-note-title">A note from the delivery team</h2><div class="adapt-letter">${q.sentences.map((s,i)=>`<p><span class="tiny">${i+1}.</span> ${esc(s)}</p>`).join('')}</div>${hear('reading',q.sentences.join(' ')+' '+q.prompt,'Hear the delivery note')}<p>${q.prompt}</p><fieldset><legend>Choose a parcel tag</legend><div class="living-options adapt-tags">${tags.map(t=>button(`data-adapt-tag="${t}" aria-pressed="${s.tag===t}"`,tagArt(t)+`${t[0].toUpperCase()+t.slice(1)} tag`,s.tag===t)).join('')}</div></fieldset>${q.depth===3?`<fieldset><legend>Which sentence is your evidence?</legend><div class="living-options adapt-evidence">${q.sentences.map((text,i)=>button(`data-adapt-evidence="${i}" aria-pressed="${s.evidence===i}"`,`${i+1}. ${esc(text)}`,s.evidence===i)).join('')}</div></fieldset>`:''}${button('data-adapt-submit="reading"','Check our note',false,s.matched||s.tag===null||q.depth===3&&s.evidence===null)}<p id="adapt-reading-feedback" class="spiral-feedback" role="status">${s.matched?'That tag and clue fit our delivery. Let’s find it.':s.count?'Look again at who each parcel is for. We can read it together.':'The food is sealed for the café. We leave the animal’s own food and shelter alone.'}</p>${help('reading','Read it together')}${s.help?`<p class="hint" id="adapt-reading-help">${esc(q.explanation)}</p>`:''}${readingReady(r)?button('data-adapt-find','Find our sealed café parcel'):''}</section>`;}
const dots=n=>Array.from({length:n},()=>'<i></i>').join('');
function packs(t,n=t.packs){return `<div class="spiral-packs" role="img" aria-label="${n} ${n===1?'pack':'packs'}, ${t.bites} bites per pack">${Array.from({length:n},(_,i)=>`<figure class="spiral-pack"><div aria-hidden="true">${dots(t.bites)}</div><figcaption>Pack ${i+1} · ${t.bites} bites</figcaption></figure>`).join('')}</div>`;}
function parcel(r,state){const t=r.task,s=r.math,q=mathQuestion(t),resolved=s.matched||s.help,n=state.cafe?.stock?.[t.ingredientId],full=!Number.isSafeInteger(n)||n+total(t)>180;
 const picture=q.depth===2&&!resolved?`<div class="adapt-inverse"><figure><div class="adapt-loose" aria-hidden="true">${dots(total(t))}</div><figcaption>${total(t)} bites altogether; the pack count is hidden.</figcaption></figure><figure>${packs(t,1)}<figcaption>One unit pack holds ${t.bites} bites.</figcaption></figure></div>`:packs(t);
 return `<section class="living-parcel"><p class="place-name">${names.math} · ${depths.math[q.depth-1]}</p><h2 id="adapt-parcel-title">A parcel for hungry neighbors</h2><div class="adapt-food">${foodArt(t.ingredientId,food(t).name)}<p>${food(t).name} · sealed pretend café food.<br>We leave the animal and its habitat undisturbed.</p></div>${picture}<p class="adapt-question">${q.prompt}</p>${hear('math',q.prompt,'Hear the parcel question')}<form id="adapt-count-form"><label for="adapt-count">Our ${q.depth===2?'pack count':q.depth===3?'plan for tomorrow':'bite count'}</label><div class="spiral-count-row"><input id="adapt-count" inputmode="numeric" autocomplete="off" maxlength="20" value="${esc(s.input)}"><button class="primary" type="submit" ${s.matched?'disabled':''}>Check our idea</button></div></form><p class="spiral-number-feedback" id="adapt-math-feedback" role="status">${s.matched?'That fits the delivery question.':s.count?'Let’s try a picture, a known fact, or the worked example.':'Try an idea, or work through it with Moss.'}</p>${help('math','Work it through with Moss')}${s.help?`<div class="hint" id="adapt-math-help"><p>${q.explanation}</p>${q.depth===3?`<h3>Tomorrow’s plan</h3>${t.packs===1?'<p>No packs tomorrow: 0 bites.</p>':packs(t,t.packs-1)}`:''}</div>`:''}<fieldset><legend>How did we work? (Optional)</legend><div class="living-options">${[['knew','I knew it'],['worked','I worked it out'],['counted','I counted'],['together','We did it together'],['unreported','Leave unreported']].map(([m,label])=>button(`data-adapt-method="${m}" aria-pressed="${s.method===m}"`,label,s.method===m)).join('')}</div></fieldset><div class="spiral-carry">${button('data-adapt-carry',resolved?`Carry today’s ${total(t)} bites to the café`:'Carry today’s parcel',false,!resolved||full)}${full?'<p role="status">The jar holds 180 bites. Our parcel can wait while we use some food at the café, or we can leave it behind.</p>':''}<a class="secondary" href="#cafe">Visit the café</a></div><p class="tiny">A pack-count answer or tomorrow’s plan never changes today’s full parcel.</p></section>`;
}
function ending(r){return `<section class="living-parcel spiral-ending">${spiralAnimalArt(spiralCase(r.task.caseId).animal)}<h2 id="adapt-ending">${r.carried?'Food for our neighbors. Room for wildlife.':'Another trail in our notebook.'}</h2><p>${r.carried?`${total(r.task)} ${food(r.task).name} bites reached the café once.`:'We left the parcel. No food was added; unanswered questions stay unobserved.'}</p><p>${spiralAnimal(spiralCase(r.task.caseId).animal).planning}</p><div class="summary-links">${button('data-adapt-start','Follow another trail')}<a class="secondary" href="#cafe">Visit the café</a><a class="secondary" href="#wonder/many-rectangles">Plan the planting beds</a><a href="#living">Choose a trail</a></div></section>`;}
export function adaptivePage(state,slug){const s=spiralState(state),r=s?.current;if(!s&&Object.hasOwn(state,'livingExploration'))return spiralPage(state,slug);
 if(slug!=='visit'||!r||r.revision!=='habitat-round-2')return spiralPage(state,slug).replace('<details class="panel"><summary>Grown-ups: a spiral of ideas',settings(state)+'<details class="panel"><summary>Grown-ups: a spiral of ideas');
 return `<div class="living-page spiral-page"><header class="page-heading"><a class="back" href="#living">← Our garden trails</a><p class="place-name">Living Garden · Visit ${r.id+1}</p><h1>Look a little closer.</h1><p>A familiar search, with new things to notice.</p></header>${spiralClosed(r)?ending(r):progress(r)+(r.found?parcel(r,state):science(r))+`<div class="spiral-pause"><a href="#living">Pause and choose a trail</a>${button('data-adapt-leave','Leave this parcel and try another trail')}<p class="tiny">Leaving closes this visit without supplies. Help and other destinations stay open.</p></div>`}${settings(state)}<details class="panel"><summary>Grown-ups: why these questions?</summary>${strands.map(k=>`<p><strong>${names[k]} · ${depths[k][r.task.teaching.depths[k]-1]}.</strong> ${esc(r.task.teaching.reasons[k])} ${r.task.teaching.familiar[k]?'Previously offered task or relation.':'First offer of this task key.'}</p>`).join('')}<p>Suggestions use a few different finished tasks, separately for each strand. Help, audio requests, retries and familiarity stay separate. Pictures are authored clues, not field measurements. Reading selections do not establish decoding, and parcel answers do not certify fact recall. No learner data leaves this browser.</p></details>${learningInvitations('living')}</div>`;
}
export function adaptiveNotes(state){const s=spiralState(state);if(!s)return spiralNotes(state);const rounds=[...s.history,...(s.current?[s.current]:[])].filter(r=>r.revision==='habitat-round-2');return spiralNotes(state)+`<details class="panel"><summary>Living Garden · growing invitations (${rounds.length} retained visits)</summary><p>Only actual responses from closed v2 visits inform suggestions. Latest assessed visit per task key, at most six keys since the strand’s last depth change. Two new first-response matches or three familiar ones can invite depth; two recent distinct retries can invite a smaller step. Scoped support is neutral. A retry ends a clean run; a clean match ends a retry run. Choices never lock a trail. Retained: 24 closed visits plus current; immutable first response and total tries survive each strand’s recent-24 response limit.</p>${strands.map(k=>{const x=adaptiveSuggestion(state,k);return `<p><strong>${names[k]} next:</strong> ${depths[k][x.level-1]}. ${esc(x.reason)}</p>`;}).join('')}${rounds.map(r=>`<section><h3>Visit ${r.id+1} · ${esc(spiralCase(r.task.caseId).title)}</h3>${strands.map(k=>{const x=r[k],h=r.task.teaching,first=x.first;return `<p><strong>${names[k]} · ${depths[k][h.depths[k]-1]}</strong>: ${esc(h.reasons[k])} Key ${esc(h.keys[k])}; ${h.familiar[k]?'familiar':'new at start'}. ${x.count?`${x.count} response(s); first ${first.correct?'matched':'did not match'}${first.afterHelp?' with explanation':''}${first.afterAudio?' after audio request':''}${first.afterVocabulary?' after vocabulary':''}${first.afterTogether?' with a together method at response':''}. Latest ${x.attempts.at(-1).correct?'matched':'did not match'}.`:'Unobserved: no submitted response.'} Help opened: ${x.help?'yes':'no'}; audio requested: ${x.audio?'yes':'no'} (playback unobserved).${k==='math'?` Method: ${x.method}; prior product seen: ${h.priorFactSeen?'yes':'no'}. Counting/deriving is distinct from recall.`:''}</p><details><summary>Recent ${names[k].toLowerCase()} responses</summary><pre>${esc(JSON.stringify({first:x.first,total:x.count,recent:x.attempts},null,2))}</pre></details>`;}).join('')}<p>Original parcel ${r.task.packs} × ${r.task.bites}. ${r.carried?'Carried once':r.left?'Left without supplies':r.found?'Found and waiting':'Still searching'}. Input: ${esc(r.math.input)}.</p></section>`).join('')}<p>These are modest practice suggestions, not independent reading, grade, placement or mastery evidence.</p></details>`;}
export function bindAdaptive(state,{save,render,navigate,focus}){
 const bind=(selector,act,target)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(act(b)){save();render();focus?.(typeof target==='function'?target(b):target);}}));
 document.querySelectorAll('[data-adapt-choice]').forEach(el=>el.addEventListener('change',()=>{if(setAdaptiveChoice(state,el.dataset.adaptChoice,el.value==='auto'?'auto':Number(el.value)))save();}));
 bind('[data-adapt-start]',()=>startAdaptiveSpiral(state),'h1');
 bind('[data-adapt-inspect]',b=>inspectAdaptive(state,Number(b.dataset.adaptInspect)),b=>`#adapt-clue-${b.dataset.adaptInspect}`);
 bind('[data-adapt-science-place]',b=>chooseAdaptive(state,'science','place',Number(b.dataset.adaptSciencePlace)),b=>`[data-adapt-science-place="${b.dataset.adaptSciencePlace}"]`);
 bind('[data-adapt-science-detail]',b=>chooseAdaptive(state,'science','detail',b.dataset.adaptScienceDetail),b=>`[data-adapt-science-detail="${b.dataset.adaptScienceDetail}"]`);
 bind('[data-adapt-vocabulary]',()=>supportAdaptive(state,'science','vocabulary'),'#adapt-vocabulary');
 bind('[data-adapt-change]',()=>revealAdaptiveChange(state),'#adapt-change-picture');
 bind('[data-adapt-tag]',b=>chooseAdaptive(state,'reading','tag',b.dataset.adaptTag),b=>`[data-adapt-tag="${b.dataset.adaptTag}"]`);
 bind('[data-adapt-evidence]',b=>chooseAdaptive(state,'reading','evidence',Number(b.dataset.adaptEvidence)),b=>`[data-adapt-evidence="${b.dataset.adaptEvidence}"]`);
 bind('[data-adapt-submit]',b=>submitAdaptive(state,b.dataset.adaptSubmit),b=>`#adapt-${b.dataset.adaptSubmit}-feedback`);
 bind('[data-adapt-help]',b=>supportAdaptive(state,b.dataset.adaptHelp,'help'),b=>`#adapt-${b.dataset.adaptHelp}-help`);
 bind('[data-adapt-find]',()=>findAdaptive(state),'#adapt-parcel-title');
 bind('[data-adapt-method]',b=>chooseAdaptive(state,'math','method',b.dataset.adaptMethod),b=>`[data-adapt-method="${b.dataset.adaptMethod}"]`);
 bind('[data-adapt-carry]',()=>carryAdaptive(state),'#adapt-ending');
 document.querySelector('#adapt-count')?.addEventListener('input',e=>{if(chooseAdaptive(state,'math','input',e.target.value))save();});
 document.querySelector('#adapt-count-form')?.addEventListener('submit',e=>{e.preventDefault();if(submitAdaptive(state,'math')){save();render();}else{const message=document.querySelector('#adapt-math-feedback');if(message)message.textContent='Try a whole number from 0 to 999, or work through it with Moss.';}focus?.('#adapt-math-feedback');});
 document.querySelectorAll('[data-adapt-audio]').forEach(b=>b.addEventListener('click',()=>{if(supportAdaptive(state,b.dataset.adaptAudio,'audio'))save();}));
 document.querySelectorAll('[data-adapt-leave]').forEach(b=>b.addEventListener('click',()=>{if(leaveAdaptive(state)){save();navigate('#living');}}));
}
